/**
 * scripts/generate-tool-mount.mjs
 * ───────────────────────────────────────────────────────────────────────────
 * Generates components/smarttools/ToolMount.tsx from the authoritative loader
 * map in lib/tools/loaders.ts.
 *
 * The generated file is a Client Component whose 110 next/dynamic declarations
 * live at module scope with LITERAL import paths. That shape is what makes
 * webpack emit one async chunk per tool (proven by build spike: catch-all
 * First Load JS 420 kB -> 109 kB). Deriving paths from route params or template
 * strings would recreate an eager context module and regress the bundle, so the
 * generator only ever emits quoted literals.
 *
 * Usage: node scripts/generate-tool-mount.mjs [--check]
 *   --check  exit non-zero if the checked-in file differs (CI / regression).
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const LOADERS = path.join(ROOT, 'lib/tools/loaders.ts');
const OUT = path.join(ROOT, 'components/smarttools/ToolMount.tsx');

const loaderSrc = fs.readFileSync(LOADERS, 'utf8');
const entries = [...loaderSrc.matchAll(/'([a-z0-9-]+)':\s*\(\)\s*=>\s*import\('@\/components\/tools\/([a-z0-9-]+)'\)/g)].map(
  (m) => ({ slug: m[1], component: m[2] })
);

if (entries.length === 0) {
  console.error('line-arrest: no loader entries discovered in', LOADERS);
  process.exit(2);
}

const registryLines = entries
  .map(
    (e) =>
      `  '${e.slug}': dynamic(() => import('@/components/tools/${e.component}'), {\n    loading: () => <ToolSkeleton />,\n  }) as unknown as ToolComponent,`
  )
  .join('\n');

const file = `'use client';
/**
 * components/smarttools/ToolMount.tsx
 * ───────────────────────────────────────────────────────────────────────────
 * Client boundary that lazy-loads exactly ONE SmartTool component per slug.
 *
 * AUTO-GENERATED by scripts/generate-tool-mount.mjs from lib/tools/loaders.ts.
 * DO NOT EDIT BY HAND — edit the generator (or the loader map) and regenerate:
 *
 *     node scripts/generate-tool-mount.mjs
 *
 * Why this exists (Tool-036 performance fix):
 *   The catch-all route (app/smarttools/[category]/[tool]/page.tsx) is a Server
 *   Component. When it resolved a tool with \`await getToolComponent(slug)\` and
 *   rendered <ToolComponent /> directly, React's RSC client-reference collector
 *   had to include EVERY 'use client' module reachable through the loader map in
 *   that route's client chunk. Measured: 112 eager module references and a
 *   420 kB First Load JS carrying all 110 tool components on every tool page.
 *
 *   Mounting the tool through this client boundary — with the 110 next/dynamic
 *   declarations at module scope and LITERAL import paths — makes each entry a
 *   real async chunk again. Webpack emits
 *       "slug": dynamic(() => Promise.all([l.e(chunk)]).then(l.bind(l, id)))
 *   and the browser downloads only the requested tool's chunk. Measured after:
 *   114 kB First Load JS.
 *
 * SSR is preserved: next/dynamic defaults to ssr:true, so the requested tool is
 * server-rendered (its <h1> stays in the initial HTML) and hydrates on the
 * client. Only the one requested component is ever resolved; the other 109 are
 * not rendered or eagerly imported.
 *
 * Slug safety: the slug is supplied by a trusted server component (validated
 * against the published catalog) and re-guarded here by an allow-list — an
 * unknown slug renders a defensive placeholder and imports nothing.
 */
import React from 'react';
import dynamic from 'next/dynamic';

type ToolProps = Record<string, never>;
type ToolComponent = React.ComponentType<ToolProps>;

/** Shown while the single requested tool chunk is fetched. */
function ToolSkeleton() {
  return (
    <div
      data-testid="tool-mount-skeleton"
      className="h-40 animate-pulse rounded-2xl border border-white/10 bg-white/[0.03]"
      aria-hidden="true"
    />
  );
}

/**
 * Allow-listed slug -> lazily-imported component. Module scope is deliberate:
 * each entry must be a top-level next/dynamic declaration with a literal import.
 */
const TOOL_COMPONENTS: Record<string, ToolComponent> = {
${registryLines}
};

/**
 * Renders the one tool identified by \`slug\`. Unknown slugs import nothing and
 * render a defensive placeholder (the server page already calls notFound()).
 */
export default function ToolMount({ slug }: { slug: string }): React.ReactElement {
  const Component = TOOL_COMPONENTS[slug];
  if (!Component) {
    return <div data-testid="tool-mount-missing" />;
  }
  return <Component {...({} as ToolProps)} />;
}
`;

if (process.argv.includes('--check')) {
  const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (current !== file) {
    console.error('ToolMount.tsx is out of date. Run: node scripts/generate-tool-mount.mjs');
    process.exit(1);
  }
  console.log('ToolMount.tsx is up to date.');
  process.exit(0);
}

fs.writeFileSync(OUT, file);
console.log(`wrote ${OUT} with ${entries.length} entries`);
